  "guide.home.bigscreen": "大画面モード",
  "guide.home.bigscreen.body": "テレビやコントローラー向けの全画面ランチャーです。F11 を押すか、コントローラーの Start を長押しすると切り替わります。",
  "guide.home.settings": "設定",
  "guide.home.settings.body": "テーマ、言語、ゲームのメモリ、Java、ファイルの保存先、バックアップ。すべてのインスタンスはこの設定から始まります。",
  "guide.home.caret": "ほかの遊び方",
  "guide.home.caret.body": "プレイするアカウントを選んだり、Mod なしで起動したり、すぐにサーバーへ参加したりできます。",
  "guide.home.quickjoin": "サーバーにすぐ参加",
  "guide.home.quickjoin.body": "最近遊んだサーバーと、今オンラインの人がわかります。参加を押すと合ったインスタンスを起動して接続します。",
  "guide.library.import": "Modパックをインポート",
  "guide.library.import.body": "友だちやサイトからもらった .zip や .mrpack はありますか？ここで選ぶとインスタンスになります。",
  "guide.library.migrate": "前のランチャーから移行",
  "guide.library.migrate.body": "Prism、MultiMC、CurseForge、Modrinth App などからインスタンスをコピーします。ワールドや Mod もそのままです。",
  "guide.library.groups": "グループ",
  "guide.library.groups.body": "グループ名をクリックすると折りたためます。つまみをドラッグして並べ替え、カードはドラッグでグループ間を移動できます。",
  "guide.library.select": "まとめて選ぶ",
  "guide.library.select.body": "カードにチェックを入れると、まとめて移動、エクスポート、削除できます。Shift+クリックで範囲を選べます。",
  "guide.instance.version": "バージョンとローダー",
  "guide.instance.version.body": "クリックで Minecraft のバージョンや Mod ローダーを変更できます。先に ResinCraft が Mod がそのまま使えるか確認します。",
  "guide.instance.export": "共有する",
  "guide.instance.export.body": "友だち向け、または Modrinth や CurseForge 向けに Modパックファイルとしてエクスポートします。",
  "guide.instance.kinds": "Mod、パック、シェーダー",
  "guide.instance.kinds.body": "このインスタンスの Mod、リソースパック、シェーダーを切り替えて表示します。",
  "guide.instance.add": "もっと追加",
  "guide.instance.add.body": "すべてのサイトを検索して、このインスタンスに入れられます。Mod に必要なものも一緒に入ります。",
  "guide.instance.updates": "更新",
  "guide.instance.updates.body": "ここにあるものすべての新しいバージョンを探し、どれを更新するか選べます。",
  "guide.instance.toggle": "Mod をオフにする",
  "guide.instance.toggle.body": "スイッチで Mod を削除せずに無効にできます。クラッシュの原因を探すときに便利です。",
  "guide.quickjoin.last": "前回の続き",
  "guide.quickjoin.last.body": "最後に参加したサーバーです。ワンクリックでインスタンスを起動して接続します。",
  "guide.quickjoin.friends": "友だちと遊ぶ",
  "guide.quickjoin.friends.body": "ポート開放なしでワールドを友だちに公開したり、コードで友だちのワールドに参加したりできます。",
  "guide.quickjoin.worlds": "あなたのワールド",
  "guide.quickjoin.worlds.body": "すべてのインスタンスのシングルプレイワールドです。ここから直接遊べます。",
