  "guide.server.tabs": "そのほかの機能",
  "guide.server.tabs.body": "プレイヤー、プラグインや Mod、サーバー設定、フォルダーなどがタブごとにあります。",
  "guide.splayers.requests": "ホワイトリスト申請",
  "guide.splayers.requests.body": "プレイヤーは参加を申請できます。ここで承認または拒否します。",
  "guide.splayers.add": "プレイヤーを追加",
  "guide.splayers.add.body": "名前を入力して、ホワイトリスト、オペレーター、BAN リストに追加します。",
  "guide.saddons.add": "プラグインを追加",
  "guide.saddons.add.body": "Modrinth、CurseForge、Hangar、SpigotMC を検索して、ワンクリックでインストールできます。",
